// Valida lo que manda el panel (lib/tienda-web/clientes/cuentas.ts): { evento: 'tienda_codigo', codigo_id }.
// Solo eso: el correo y el código se leen de la MySQL en el nodo siguiente (el webhook es publico).
const body = $json.body || {};
const id = parseInt(body.codigo_id, 10);
if (body.evento !== 'tienda_codigo' || !(id > 0)) return null;
return { json: { id } };

// Arma el correo con el código de acceso de «Mi cuenta» de la tienda web, con la fila de "Leer código"
// (tienda_codigos). Nada viene del webhook (es público): el panel guardó el correo y el código
// (lib/tienda-web/clientes/cuentas.ts). Sin fila = ya se mandó, venció o lo reemplazó otro.
const c = $json;
if (!c || !c.id || !/^\d{6}$/.test(String(c.codigo_envio || ''))) return null;

const esc = (v) => String(v == null ? '' : v).replace(/[&<>"']/g, (x) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[x]));
const para = String(c.correo || '').trim();
if (!/^[^\s@<>,;"']+@[^\s@<>,;"']+\.[a-z]{2,}$/i.test(para)) return null;
const codigo = String(c.codigo_envio);
const visible = codigo.slice(0, 3) + ' ' + codigo.slice(3);
const nombre = String(c.nombre || '').trim();
const asunto = 'Tu código de acceso a SUPRICOM: ' + visible;

const html = '<!doctype html><html><body style="margin:0;background:#F4F5F2;font-family:Arial,Helvetica,sans-serif;color:#0B0D12">'
  + '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#F4F5F2;padding:24px 12px"><tr><td align="center">'
  + '<table role="presentation" width="520" cellpadding="0" cellspacing="0" style="max-width:520px;width:100%;background:#FFFFFF;border:1px solid #E0E2DB;border-radius:16px">'
  + '<tr><td style="padding:32px 32px 8px"><p style="margin:0;font-size:20px;font-weight:bold;letter-spacing:-.01em">SUPRICOM</p>'
  + '<h1 style="margin:20px 0 8px;font-size:22px;line-height:1.3">Tu código de acceso</h1>'
  + '<p style="margin:0;font-size:15px;line-height:1.55;color:#565C68">' + (nombre ? 'Hola, ' + esc(nombre) + '. ' : '') + 'Usa este código para crear o recuperar la contraseña de tu cuenta en la tienda de SUPRICOM.</p></td></tr>'
  + '<tr><td style="padding:20px 32px"><p style="margin:0;padding:18px;border-radius:12px;background:#F1F2EE;text-align:center;font-family:\'Courier New\',monospace;font-size:34px;font-weight:bold;letter-spacing:.2em">' + esc(visible) + '</p></td></tr>'
  + '<tr><td style="padding:0 32px 28px"><p style="margin:0;font-size:14px;line-height:1.55;color:#565C68">Vence en 15 minutos. Si no lo pediste, ignora este correo: nadie puede entrar a tu cuenta sin este código.</p></td></tr>'
  + '</table></td></tr></table></body></html>';
const texto = [
  'SUPRICOM · Tu código de acceso', '',
  (nombre ? 'Hola, ' + nombre + '. ' : '') + 'Usa este código para crear o recuperar la contraseña de tu cuenta en la tienda de SUPRICOM:', '',
  visible, '',
  'Vence en 15 minutos. Si no lo pediste, ignora este correo: nadie puede entrar a tu cuenta sin este código.',
].join('\n');

const b64 = (t) => Buffer.from(t, 'utf8').toString('base64');
const partir = (t) => t.replace(/.{1,76}/g, (l) => l + '\r\n');
const limite = 'codigo-' + c.id + '-' + Date.now().toString(36);
const mime = [
  'From: =?UTF-8?B?' + b64('Tienda web SUPRICOM') + '?= <dmedina@supricom.com.ve>',
  'To: ' + para,
  'Subject: =?UTF-8?B?' + b64(asunto) + '?=',
  'MIME-Version: 1.0',
  'Content-Type: multipart/alternative; boundary="' + limite + '"',
  '',
  '--' + limite,
  'Content-Type: text/plain; charset="UTF-8"',
  'Content-Transfer-Encoding: base64',
  '',
  partir(b64(texto)),
  '--' + limite,
  'Content-Type: text/html; charset="UTF-8"',
  'Content-Transfer-Encoding: base64',
  '',
  partir(b64(html)),
  '--' + limite + '--',
  '',
].join('\r\n');
const raw = Buffer.from(mime, 'utf8').toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');

return { json: { codigo_id: Number(c.id), para, raw } };
